^white;최대 체력^reset;: ^red;-5%^reset;
^white;최대 에너지^reset;: ^red;-10%^reset;
^white;에너지 재생^reset;: ^red;-25%^reset;
^white;공격 배율^reset;: ^green;+10%^reset;
^darkgray;방어력: -^reset;
    ^#00A9FF;저항^reset;
^white;화염 저항^reset;: ^red;-25%^reset;
^darkgray;전기 저항: -^reset;
^darkgray;독 저항: -^reset;
^white;냉기 저항^reset;: ^green;+35%^reset;
^darkgray;물리 저항: -^reset;
